sources.base.cod:
type Entity;
data First <: Entity { value::i64; }
data Second <: Entity { value::i64; }
function score(x::First)::i64 { 1 }
function score(x::Second)::i64 { 2 }
function relay(x::Entity)::i64 { score(x) }
export Entity; export First; export Second; export score; export relay;

results.integration:
using "base.cod" First;
using "base.cod" score as all;
export import "base.cod" relay;

results.entry:
using symbol "std:io" @print;
using "base.cod" Second;
using "integration.cod" relay as adapted;
symbol @arena::region;
effect @arena <- region(4096u64);
behave @print(adapted(deref(alloc @arena Second(9))));

